template.script:
(function () {
    var STORAGE_KEY = 'ws_sede_pref';
    var params = new URLSearchParams(window.location.search);

    if (params.has('sede')) {
        // El usuario eligió sede explícitamente → guardar preferencia
        localStorage.setItem(STORAGE_KEY, params.get('sede'));
    } else {
        // Sin sede en URL → aplicar preferencia guardada
        var saved = localStorage.getItem(STORAGE_KEY);
        if (saved && saved !== 'all') {
            params.set('sede', saved);
            window.location.replace(window.location.pathname + '?' + params.toString());
        }
    }
})();
